#ifndef POCKETMC_MODS_WOODLAND_DATA_H__
#define POCKETMC_MODS_WOODLAND_DATA_H__

// Plain data tables generated by tools/gen_woodland.py from the original jar.

struct WlCube    { float ox, oy, oz, sx, sy, sz, u, v, inflate; int mirror; };
struct WlBone    { const char* name; const char* parent; float px, py, pz, rx, ry, rz; int cubeStart, cubeCount; };
struct WlGeo     { const char* id; int texW, texH; int boneStart, boneCount; };
struct WlKey     { float t, x, y, z; };
struct WlChannel { const char* bone; int type; int keyStart, keyCount; };   // type 0 rot, 1 pos, 2 scale
struct WlAnim    { const char* name; float length; int loop; int chanStart, chanCount; }; // loop 0 once, 1 loop, 2 hold
struct WlMobDef  { const char* name; const char* cls; const char* geo; const char* tex; const char* animPrefix;
                   float w, h, health, speed, damage, follow; int flags; };
struct WlRun       { unsigned short n; unsigned char id; unsigned char data; };
struct WlStructure { const char* name; int sx, sy, sz; int runStart, runCount; };

enum { WL_MOB_HOSTILE = 1, WL_MOB_AGGRESSIVE = 2, WL_MOB_FOLLOWS = 4, WL_MOB_WANDERS = 8 };

extern const WlCube WL_CUBES[];
extern const WlBone WL_BONES[];
extern const WlGeo  WL_GEOS[];
extern const int    WL_GEO_COUNT;
extern const WlKey  WL_KEYS[];
extern const WlChannel WL_CHANNELS[];
extern const WlAnim WL_ANIMS[];
extern const int    WL_ANIM_COUNT;
extern const WlMobDef WL_MOBS[];
extern const int    WL_MOB_COUNT;
extern const WlRun  WL_RUNS[];
extern const WlStructure WL_STRUCTURES[];
extern const int    WL_STRUCTURE_COUNT;

#endif
